  public static void Begin(){
   if(Armed)throw new InvalidOperationException("A mission graph run is already armed");report=new Report{unity=Application.unityVersion,phase="configured",nonce=Guid.NewGuid().ToString("N"),beginDomain=Domain};
   try{
    Need(Full(Path.Combine(Application.dataPath,".."))==Full(Project),"Exact Root-owned Project");Need(!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling,"Fresh EditMode entry");Need(!EditorSettings.enterPlayModeOptionsEnabled,"Unity default domain reload is enabled");
    var args=Environment.GetCommandLineArgs();int k=Array.IndexOf(args,"-sfmMissionGraphOutput");Need(k>=0&&k+1<args.Length,"Owned output argument");string output=Full(args[k+1]);Need(output.StartsWith(Full(Path.Combine(Project,"../runs"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!Directory.Exists(output)&&!File.Exists(output),"Fresh output inside Root NPC runs");
