    Directory.CreateDirectory(output);SessionState.SetString(Key+"output",output);SessionState.SetString(Key+"deadline",DateTime.UtcNow.AddSeconds(180).Ticks.ToString());SessionState.SetBool(Key+"armed",true);SessionState.SetInt(Key+"exit",3);Save();EditorSceneManager.OpenScene(contract.scene,OpenSceneMode.Single);EditorApplication.isPlaying=true;
   }catch(Exception e){Finish(e);}
