  static void Changed(PlayModeStateChange state){if(!Armed)return;Load();if(state==PlayModeStateChange.EnteredPlayMode){report.playDomain=Domain;report.domainReloadObserved=report.beginDomain!=Domain;report.actualEditorPlayMode=EditorApplication.isPlaying;report.phase="waiting-actor";Save();}if(state==PlayModeStateChange.EnteredEditMode){if(report.phase!="finished"){report.failure="Exited PlayMode before probe completion";report.passed=false;Write();SessionState.SetInt(Key+"exit",3);}SessionState.SetBool(Key+"armed",false);int exit=SessionState.GetInt(Key+"exit",3);EditorApplication.delayCall+=()=>EditorApplication.Exit(exit);}}
  static void Log(string message,string stack,LogType kind){if(!Armed||!EditorApplication.isPlaying)return;Load();if(kind==LogType.Error||kind==LogType.Exception||kind==LogType.Assert)report.engineErrors.Add(kind+": "+message);if(kind==LogType.Exception||kind==LogType.Assert)report.runtimeExceptions.Add(kind+": "+message);Save();}
  static void Pump(){if(!Armed||busy)return;busy=true;try{Load();if(DateTime.UtcNow.Ticks>long.Parse(SessionState.GetString(Key+"deadline","0")))throw new TimeoutException("Owned PlayMode180s deadline");if(report.phase!="waiting-actor"||!EditorApplication.isPlaying)return;var bridges=UnityEngine.Object.FindObjectsOfType<OriginalMovementMvpBridge>();if(bridges.Length!=1)return;var bridge=bridges[0];if(!string.IsNullOrEmpty(bridge.Failure))throw new Exception(bridge.Failure);var core=bridge.originalCoreData;if(!bridge.Ready||core==null||!core.Initialized||bridge.BoundState.CurrentAction==null)return;
    // Wait for the existing original action observer's non-smoke Start to bind the real master None action.
    if(Time.frameCount<3||((int)bridge.BoundState.CurrentAction.Type)!=-1)return;RunGraph(bridge,core);Finish(null);
   }catch(Exception e){Finish(e);}finally{busy=false;}}
  static void PinMethod(Type type,string name){foreach(var m in type.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance).Where(x=>x.DeclaringType==type&&x.Name==name)){var b=m.GetMethodBody();Need(b!=null,"Editor method body: "+type.FullName+"."+name);using(var h=SHA256.Create())report.methodPins.Add(new MethodPin{owner=type.FullName,method=m.ToString(),moduleMVID=m.Module.ModuleVersionId.ToString(),token=m.MetadataToken,bytes=b.GetILAsByteArray().Length,ILSHA256=BitConverter.ToString(h.ComputeHash(b.GetILAsByteArray())).Replace("-","")});}}
  static void PinCtor(Type type){foreach(var m in type.GetConstructors(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance)){var b=m.GetMethodBody();Need(b!=null,"Editor actual original ctor body: "+type.FullName);using(var h=SHA256.Create())report.methodPins.Add(new MethodPin{owner=type.FullName,method=m.ToString(),moduleMVID=m.Module.ModuleVersionId.ToString(),token=m.MetadataToken,bytes=b.GetILAsByteArray().Length,ILSHA256=BitConverter.ToString(h.ComputeHash(b.GetILAsByteArray())).Replace("-","")});}}
  static void RunGraph(OriginalMovementMvpBridge bridge,CoreGameplayData core){
   report.phase="running-original-graph";Save();Need(report.domainReloadObserved&&report.actualEditorPlayMode,"Entered actual PlayMode after domain reload");report.editorGameSHA256=Hash(typeof(MissionManager).Assembly.Location);report.playerGameSHA256=Hash(contract.playerGame.path);report.sourceContractSHA256=Hash(contract.sourceContract.path);Need(report.editorGameSHA256==contract.editorGame.sha256,"Loaded EditorGame exact measured image");Need(report.editorGameSHA256!=report.playerGameSHA256,"Editor/Player images separately reported");report.startFrame=Time.frameCount;
   Need(bridge.UsesOriginalConstructors&&bridge.Ready&&core.Initialized,"Existing real actor constructors/core are ready");Need(ReferenceEquals(PlayerController.Instance,bridge.BoundPlayer)&&ReferenceEquals(PlayerController.Instance.Pca,bridge.BoundAccessor),"Same original singleton Player/PCA");Need(InGameManager.Instance!=null&&InGameManager.Instance.InGameReferencer!=null&&InGameManager.Instance.TempInGameState!=null&&InGameUiManager.Instance!=null&&PlayerFacade.Instance!=null,"Existing original graph dependencies");
   var referencer=InGameManager.Instance.InGameReferencer;if(referencer.Player==null){referencer.Player=bridge.BoundPlayer;report.cachedPlayerBindingAdded=true;}Need(ReferenceEquals(referencer.Player,bridge.BoundPlayer),"Cached actual player binding (owned wiring only)");Need(ReferenceEquals(AssetReferencer.Instance.MMission,core.Mission)&&AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(core.Mission))==contract.masterGUID,"Original real MMission master identity");
   var data=GameState.GameStateData;Need(data!=null,"Existing original GameStateData constructor");report.startingRp=data.CurrentRp;report.startingEarned=data.CurrentEarnThisTimeRp;Need(report.startingRp==0d&&report.startingEarned==0d,"Constructor zero RP and round earnings; no owned funds");Need(data.MissionSatisfyDict!=null&&data.MissionEarnRpDict!=null&&data.MissionAchieveCountDict!=null&&data.MissionMaxRpBonus100Dict!=null,"Original constructor mission collections");Need(data.MissionSatisfyDict.Count==0&&data.MissionEarnRpDict.Count==0,"Fresh mission dictionaries before original Initialize");Need(MissionManager.Instance==null&&RandomMissionManager.Instance==null,"No competing original mission managers");
   var action=bridge.BoundState.CurrentAction;bridge.BoundState.Initialize();report.originalStateInitialized=true;Need(ReferenceEquals(action,bridge.BoundState.CurrentAction),"Original state Initialize preserves actual action");Need(bridge.BoundState.CurrentRank!=null,"Original state Initialize derived actual rank from real0Exp/MRank");report.currentRank=bridge.BoundState.CurrentRank.Rank;report.initialAction=(int)action.Type;
   var masters=MMission.GetAll();Need(masters.Count==contract.expectedAreas,"Original seven mission areas");var expected=contract.records.ToDictionary(x=>x.id);var seen=new HashSet<int>();foreach(var area in masters){foreach(var pair in area.Value.GetAll()){Need(expected.TryGetValue(pair.Key,out var rec),"Original table ID "+pair.Key);Need((int)area.Key==rec.stage&&pair.Value.Id==rec.id&&pair.Value.StageType==area.Key,"Original area/ID/ordinal assignment "+rec.id);string path=AssetDatabase.GetAssetPath(pair.Value),original=AssetDatabase.GetAssetPath(pair.Value.OriginalRecord);Need(AssetDatabase.AssetPathToGUID(path)==rec.GUID&&AssetDatabase.AssetPathToGUID(original)==rec.originalGUID,"Original record/provider GUIDs "+rec.id);Need(Hash(Path.Combine(Project,path))==rec.asset.sha256&&Hash(Path.Combine(Project,original))==rec.originalAsset.sha256,"Original serialized record bytes "+rec.id);Need(seen.Add(rec.id),"Unique original record "+rec.id);}}Need(seen.Count==196,"All196 actual records traversed");
   manager=new MissionManager();manager.Initialize();report.managerInitialized=true;Need(ReferenceEquals(MissionManager.Instance,manager)&&manager.MissionList.Count==196&&manager.MissionDict.Count==7,"Actual original manager constructor/Initialize196/7");Need(manager.MissionList.Select(x=>x.GetType()).Distinct().Count()==30,"Actual30 reflected classes");foreach(var mission in manager.MissionList)Need(mission.GetType().FullName==expected[mission.RMission.Id].className,"Actual reflected original class "+mission.RMission.Id);report.records=manager.MissionList.Count;report.areas=manager.MissionDict.Count;report.classes=manager.MissionList.Select(x=>x.GetType()).Distinct().Count();report.satisfyKeys=data.MissionSatisfyDict.Count;report.earnKeys=data.MissionEarnRpDict.Count;Need(report.satisfyKeys==196&&report.earnKeys==196&&data.MissionSatisfyDict.All(x=>x.Value==0f)&&data.MissionEarnRpDict.All(x=>x.Value==0f),"Original facade initialized all196 zero satisfy/earn keys");
   random=new RandomMissionManager();random.Initialize();report.randomInitialized=true;report.randomActive=random.IsActiveMission;Need(ReferenceEquals(RandomMissionManager.Instance,random)&&!random.IsActiveMission&&random.CurrentMission==null&&random.MissionBase!=null,"Original random constructor/Initialize inactive real list/mission-base");
   report.fade=InGameUiManager.Instance.IsOpenFade;report.isGameOver=InGameManager.Instance.TempInGameState.IsGameOver;report.isTimeStop=InGameManager.Instance.TempInGameState.IsTimeStop;Need((int)data.CurrentStageType==0,"Actual Apartment Stage0 preserved");
   foreach(var mission in manager.MissionList.Where(x=>x is MissionPoseExpose||x is MissionSitExpose||x is MissionLightingExpose)){
    var s=bridge.BoundState;var beforeAction=s.CurrentAction;var beforeHidden=s.HiddenBodyPartsByCostume;float beforeLight=s.BareyasusaFromStreetLight;double rp=data.CurrentRp,earn=data.CurrentEarnThisTimeRp;var area=NpcRouteAreaManager.Instance;bool areaValue=area!=null&&area.IsInArea;int exposed=(int)PlayerFacade.Instance.GetExposedBodyPartsByClothesAndCostume();bool value=mission.IsInCondition();Need(ReferenceEquals(s.CurrentAction,beforeAction)&&s.HiddenBodyPartsByCostume==beforeHidden&&BitConverter.ToInt32(BitConverter.GetBytes(s.BareyasusaFromStreetLight),0)==BitConverter.ToInt32(BitConverter.GetBytes(beforeLight),0)&&data.CurrentRp==rp&&data.CurrentEarnThisTimeRp==earn&&ReferenceEquals(area,NpcRouteAreaManager.Instance)&&(area==null||area.IsInArea==areaValue),"Condition has no observed critical-state mutation "+mission.RMission.Id);report.conditions.Add(new Condition{id=mission.RMission.Id,stage=(int)mission.RMission.StageType,owner=mission.GetType().FullName,recordGUID=expected[mission.RMission.Id].GUID,result=value,action=(int)s.CurrentAction.Type,mask=(int)mission.RMission.OriginalRecord.ExposedBodyPartsParam,exposed=exposed,areaPresent=area!=null,areaIn=areaValue,day=data.IsDaytime,light=s.BareyasusaFromStreetLight});if(value)report.conditionsTrue++;else report.conditionsFalse++;
   }
   Need(report.conditions.Count==17&&report.conditions.Select(x=>x.owner).Distinct().Count()==3,"All17 actual records for three new conditions observed without fabricated state");manager.OnLateUpdate();Need(data.MissionSatisfyDict.All(x=>x.Value==0f)&&data.MissionEarnRpDict.All(x=>x.Value==0f)&&data.CurrentRp==0d&&data.CurrentEarnThisTimeRp==0d,"Original manager/Base Stage0 tick yields no progression/credit");report.Stage0NoRewardTick=true;report.endingRp=data.CurrentRp;report.endingEarned=data.CurrentEarnThisTimeRp;Need(bridge.Ready&&core.Initialized,"Same actual actor remains ready");Need(report.runtimeExceptions.Count==0,"No runtime exceptions/assertions during graph probe");
   foreach(var x in new[]{Tuple.Create(typeof(MissionManager),new[]{"Initialize","OnLateUpdate","Dispose"}),Tuple.Create(typeof(RandomMissionManager),new[]{"Initialize","get_CurrentMission"}),Tuple.Create(typeof(PlayerStateModel),new[]{"Initialize"}),Tuple.Create(typeof(MissionBase),new[]{"Initialize","Update"}),Tuple.Create(typeof(MissionPoseExpose),new[]{"IsInCondition"}),Tuple.Create(typeof(MissionSitExpose),new[]{"IsInCondition"}),Tuple.Create(typeof(MissionLightingExpose),new[]{"IsInCondition"}),Tuple.Create(typeof(GameStateFacade),new[]{"GetMissionSatisfy","GetMissionEarnRp"}),Tuple.Create(typeof(MMission),new[]{"CheckInitialize","GetAll"}),Tuple.Create(typeof(MMissionArea),new[]{"Initialize","GetAll"})})foreach(var name in x.Item2)PinMethod(x.Item1,name);
   PinCtor(typeof(MissionManager));PinCtor(typeof(RandomMissionManager));manager.Dispose();Need(MissionManager.Instance==null,"Original Dispose clears only owned initialized manager");manager=null;report.endFrame=Time.frameCount;CheckPin(contract.scenePin);foreach(var p in contract.formalSources)CheckPin(p);report.passed=true;
  }
  static void Write(){string output=SessionState.GetString(Key+"output","");if(!string.IsNullOrEmpty(output)&&Directory.Exists(output))File.WriteAllText(Path.Combine(output,"mission-graph.json"),JsonUtility.ToJson(report,true)+"\n");}
  static void Finish(Exception error){if(report==null)report=new Report();if(error!=null){report.passed=false;report.failure=error.ToString();if(manager!=null){try{manager.Dispose();}catch(Exception e){report.failure+="\nDispose:"+e;}manager=null;}}report.phase="finished";report.scope=new[]{"Actual Unity Editor PlayMode/domain reload with the existing v5 owned-neutral bootstrap actor scene; new Game methods execute unhooked.","Actual original Manager196/7/30 and Random/PlayerState initialization; new conditions read actual current state, no progress/RP/action/exposure/area detection writes.","Apartment Stage0 original Base early-return tick is a zero-reward baseline, not a completed task or Result/credit/purchase acceptance.","EditorGame actual SHA/method IL observations are separate from Player913E/full guard; no automatic Editor whole-DLL equivalence claim.","Existing bridge/core bootstrap has explicitly owned neutral presentation/tutorial/clothes inputs. This probe does not claim original complete startup. One public cached-player binding to the same actor may be added and reported.","All engine errors retained; passing code-graph assertions does not accept preexisting shader/font rendering issues. Random singleton lifetime ends through Unity PlayMode domain teardown; no manual singleton replacement."};SessionState.SetInt(Key+"exit",report.passed?0:3);Save();Write();if(EditorApplication.isPlayingOrWillChangePlaymode)EditorApplication.isPlaying=false;else{SessionState.SetBool(Key+"armed",false);int exit=report.passed?0:3;EditorApplication.delayCall+=()=>EditorApplication.Exit(exit);}}
